{"files":[{"path":"lib/rate-limit.ts","content":"import { Redis } from "@upstash/redis";

type LimitOptions = {
  readonly key: string;
  readonly limit: number;
  readonly prefix: string;
  readonly windowSeconds: number;
};

export class RateLimitError extends Error {
  readonly retryAfter: number;

  constructor(retryAfter: number) {
    super("Too many requests. Please wait a moment and try again.");
    this.retryAfter = retryAfter;
  }
}

let redis: Redis | null | undefined;

function getRedisEnv() {
  const url = process.env.UPSTASH_REDIS_REST_URL?.trim() || process.env.KV_REST_API_URL?.trim();
  const token =
    process.env.UPSTASH_REDIS_REST_TOKEN?.trim() || process.env.KV_REST_API_TOKEN?.trim();

  return url && token ? { token, url } : null;
}

function getRedis() {
  if (redis !== undefined) {
    return redis;
  }

  const env = getRedisEnv();

  if (!env) {
    redis = null;
    return redis;
  }

  redis = new Redis(env);
  return redis;
}

export async function imposeRateLimit(options: LimitOptions) {
  const client = getRedis();

  if (!client) {
    return;
  }

  const now = Math.floor(Date.now() / 1000);
  const windowId = Math.floor(now / options.windowSeconds);
  const redisKey = `rate:${options.prefix}:${options.key}:${windowId}`;
  const count = await client.incr(redisKey);

  if (count === 1) {
    await client.expire(redisKey, options.windowSeconds);
  }

  if (count > options.limit) {
    const retryAfter = options.windowSeconds - (now % options.windowSeconds);
    throw new RateLimitError(retryAfter);
  }
}
"}],"concerns":[],"rationale":"Renamed the exported function from enforceRateLimit to imposeRateLimit in lib/rate-limit.ts, leaving all other content unchanged."}

{"files":[{"path":"lib/lore/chips.ts","content":"import type { FilterChip, FilterPredicate } from "@lore/core";
import { PROFILE_FIELDS } from "./fields";

/** Pure chip/label helpers shared by server compiler and client UI. */

export const FIELD_LABELS: Record<string, string> = Object.fromEntries(
  PROFILE_FIELDS.map((f) => [
    f.name,
    f.name
      .split("_")
      .map((w) => w[0]!.toUpperCase() + w.slice(1))
      .join(" "),
  ]),
);

export function predicateLabel(p: FilterPredicate): string {
  switch (p.kind) {
    case "term":
      return `${FIELD_LABELS[p.field]}: ${p.value}`;
    case "terms":
      return `${FIELD_LABELS[p.field]}: ${p.values.slice(0, 2).join(", ")}${
        p.values.length > 2 ? ` +${p.values.length - 2}` : ""
      }`;
    case "range": {
      const parts: string[] = [];
      if (p.min !== undefined) parts.push(`≥ ${p.min}`);
      if (p.max !== undefined) parts.push(`≤ ${p.max}`);
      return `${FIELD_LABELS[p.field]} ${parts.join(" and ")}`;
    }
    case "exists":
      return `Has ${FIELD_LABELS[p.field]}`;
    case "not":
      return `NOT ${predicateLabel(p.predicate)}`;
    case "geo":
      return `${FIELD_LABELS[p.field]} within ${p.radiusMiles}mi`;
    case "text":
      return `"${p.query}"`;
  }
}

export function assembleChips(
  all: FilterPredicate[],
  any: FilterPredicate[],
): FilterChip[] {
  const chips: FilterChip[] = all.map((p, i) => ({
    id: `all-${i}`,
    label: predicateLabel(p),
    predicates: [i],
    source: "extracted" as const,
    ...(p.kind === "terms" && p.values.length > 2
      ? { expansions: p.values.map(String) }
      : {}),
  }));
  if (any.length > 0) {
    chips.push({
      id: "any-group",
      label: `Any of: ${any.map(predicateLabel).join(" · ")}`,
      predicates: any.map((_, i) => i),
      source: "extracted",
    });
  }
  return chips;
}
"}],"concerns":[],"rationale":"Renamed the exported function buildChips to assembleChips in lib/lore/chips.ts as instructed."}

{"files":[{"path":"lib/auth-url.ts","content":"const LOCAL_APP_URL = "http://localhost:3000";

export function getEffectiveAppUrl() {
  return (
    normalizeAppUrl(process.env.BETTER_AUTH_URL) ??
    normalizeAppUrl(process.env.VERCEL_PROJECT_PRODUCTION_URL) ??
    normalizeAppUrl(process.env.VERCEL_URL) ??
    LOCAL_APP_URL
  );
}

export function readAppUrlHost(value: string | undefined) {
  const url = normalizeAppUrl(value);

  if (!url) {
    return undefined;
  }

  return new URL(url).host;
}

function normalizeAppUrl(value: string | undefined) {
  const trimmed = value?.trim();

  if (!trimmed) {
    return undefined;
  }

  const withProtocol = /^[a-z][a-z\d+.-]*:\/\//i.test(trimmed)
    ? trimmed
    : `https://${trimmed}`;

  try {
    const url = new URL(withProtocol);
    url.pathname = "";
    url.search = "";
    url.hash = "";

    return url.toString().replace(/\/$/, "");
  } catch {
    return undefined;
  }
}
