{"files":[{"path":"lib/chat/provisional-chat.ts","content":"const PENDING_CHAT_STORAGE_MAX_AGE_MS = 10 * 60 * 1000;
const PENDING_CHAT_STORAGE_PREFIX = "eve-chat-pending:";
const PROVISIONAL_CHAT_ID_PREFIX = "new-";

type StoredPendingChat = {
  readonly createdAt: number;
  readonly pendingUserMessage: string;
  readonly version: 1;
};

export function makeProvisionalChatId() {
  const randomId =
    globalThis.crypto?.randomUUID?.() ??
    `${Date.now()}-${Math.random().toString(36).slice(2)}`;

  return `${PROVISIONAL_CHAT_ID_PREFIX}${randomId}`;
}

export function isProvisionalChatId(chatId: string) {
  return chatId.startsWith(PROVISIONAL_CHAT_ID_PREFIX);
}

export function writePendingChatMessage(chatId: string, message: string) {
  const pendingUserMessage = message.trim();

  if (!pendingUserMessage || typeof window === "undefined") {
    return false;
  }

  try {
    window.sessionStorage.setItem(
      getPendingChatStorageKey(chatId),
      JSON.stringify({
        createdAt: Date.now(),
        pendingUserMessage,
        version: 1,
      } satisfies StoredPendingChat),
    );
    return true;
  } catch {
    return false;
  }
}

export function readPendingChatMessage(chatId: string) {
  if (typeof window === "undefined") {
    return null;
  }

  const key = getPendingChatStorageKey(chatId);
  const stored = window.sessionStorage.getItem(key);

  if (!stored) {
    return null;
  }

  try {
    const parsed = JSON.parse(stored) as Partial<StoredPendingChat>;
    const createdAt = Number(parsed.createdAt);
    const pendingUserMessage = parsed.pendingUserMessage?.trim();

    if (
      !pendingUserMessage ||
      !Number.isFinite(createdAt) ||
      Date.now() - createdAt > PENDING_CHAT_STORAGE_MAX_AGE_MS
    ) {
      window.sessionStorage.removeItem(key);
      return null;
    }

    return pendingUserMessage;
  } catch {
    window.sessionStorage.removeItem(key);
    return null;
  }
}

export function clearPendingChatMessage(chatId: string) {
  if (typeof window === "undefined") {
    return;
  }

  window.sessionStorage.removeItem(getPendingChatStorageKey(chatId));
}

function getPendingChatStorageKey(chatId: string) {
  return `${PENDING_CHAT_STORAGE_PREFIX}${chatId}`;
}
"}],"concerns":[],"rationale":"Renamed the exported function in lib/chat/provisional-chat.ts from createProvisionalChatId to makeProvisionalChatId as instructed, without touching any other file."}

{"files":[{"path":"lib/password-auth.ts","content":"import { createHash, createHmac, timingSafeEqual } from "node:crypto";

export const PASSWORD_SESSION_COOKIE_NAME = "eve_chat_session";
export const PASSWORD_SESSION_MAX_AGE = 60 * 60 * 24 * 30;

const TOKEN_VERSION = "v1";

export function getChatPassword() {
  return process.env.EVE_CHAT_PASSWORD?.trim() ?? "";
}

export function verifyChatPassword(candidate: string) {
  const expected = getChatPassword();

  if (!expected) {
    return false;
  }

  return timingSafeEqual(hash(candidate), hash(expected));
}

export function makePasswordSessionToken(now = Date.now()) {
  const expiresAt = Math.floor(now / 1000) + PASSWORD_SESSION_MAX_AGE;
  const payload = `${TOKEN_VERSION}.${expiresAt}`;
  const signature = sign(payload);

  return `${payload}.${signature}`;
}

export function verifyPasswordSessionToken(token: string | undefined, now = Date.now()) {
  if (!token) {
    return false;
  }

  const [version, expiresAtRaw, signature, ...extra] = token.split(".");
  const expiresAt = Number(expiresAtRaw);

  if (
    version !== TOKEN_VERSION ||
    !signature ||
    extra.length > 0 ||
    !Number.isSafeInteger(expiresAt) ||
    expiresAt <= Math.floor(now / 1000)
  ) {
    return false;
  }

  const expected = sign(`${version}.${expiresAt}`);

  return timingSafeEqual(hash(signature), hash(expected));
}

export function getPasswordSessionFromHeaders(headers: Headers) {
  const cookieHeader = headers.get("cookie");

  if (!cookieHeader) {
    return false;
  }

  const token = cookieHeader
    .split(";")
    .map((cookie) => cookie.trim().split("="))
    .find(([name]) => name === PASSWORD_SESSION_COOKIE_NAME)?.[1];

  return verifyPasswordSessionToken(token ? decodeURIComponent(token) : undefined);
}

export function hasSameOriginRequest(request: Request) {
  const origin = request.headers.get("origin");
  const publicHost =
    request.headers.get("x-forwarded-host") ??
    request.headers.get("host");

  if (!origin || !publicHost) {
    return false;
  }

  try {
    const originUrl = new URL(origin);
    const forwardedProtocol = request.headers.get("x-forwarded-proto");

    return (
      originUrl.host === publicHost &&
      (!forwardedProtocol || originUrl.protocol === `${forwardedProtocol}:`)
    );
  } catch {
    return false;
  }
}

function hash(value: string) {
  return createHash("sha256").update(value).digest();
}

function sign(payload: string) {
  return createHmac("sha256", getChatPassword()).update(payload).digest("base64url");
}
"}],"concerns":[],"rationale":"Renamed the exported function definition from createPasswordSessionToken to makePasswordSessionToken in lib/password-auth.ts as instructed."}

{"files":[{"path":"app/actions/chat.ts","content":""use server";

import type { HandleMessageStreamEvent, SessionState } from "eve/client";
import {
  appendChatEvent,
  clearChatPendingMessage,
  createChat,
  deleteChatForUser,
  listChatsByUser,
  markChatPendingMessage,
  saveChatSnapshot,
  saveChatSessionState,
  skipChatAuthorization,
} from "@/lib/db/queries";
import { assertChatMessageLength } from "@/lib/chat/limits";
import { RateLimitError, enforceRateLimit } from "@/lib/rate-limit";
import { getServerViewer } from "@/lib/session";
import { getSetupStatus } from "@/lib/setup";

const SEND_LIMIT = 25;
const SEND_WINDOW_SECONDS = 60 * 60;

export async function createChatAction(input?: { readonly pendingUserMessage?: string }) {
  const viewer = await requireViewer();

  if (input?.pendingUserMessage) {
    assertChatMessageLength(input.pendingUserMessage);
  }

  await enforceRateLimit({
    key: viewer.id,
    limit: SEND_LIMIT,
    prefix: "chat:create",
    windowSeconds: SEND_WINDOW_SECONDS,
  });

  return createChat(viewer.id, {
    pendingUserMessage: input?.pendingUserMessage,
  });
}

export async function checkSendLimitAction(input?: { readonly message?: string }) {
  const viewer = await requireViewer();

  try {
    if (input?.message) {
      assertChatMessageLength(input.message);
    }

    await enforceRateLimit({
      key: viewer.id,
      limit: SEND_LIMIT,
      prefix: "chat:send",
      windowSeconds: SEND_WINDOW_SECONDS,
    });

    return { allowed: true as const };
  } catch (error) {
    if (error instanceof RateLimitError) {
      return {
        allowed: false as const,
        message: error.message,
        retryAfter: error.retryAfter,
      };
    }

    throw error;
  }
}

export async function saveChatSnapshotAction(input: {
  readonly chatId: string;
  readonly events: readonly HandleMessageStreamEvent[];
  readonly session: SessionState;
}) {
  const viewer = await requireViewer();

  await saveChatSnapshot({
    chatId: input.chatId,
    events: input.events,
    session: input.session,
    userId: viewer.id,
  });

  return { ok: true };
}

export async function markChatPendingMessageAction(input: {
  readonly chatId: string;
  readonly message: string;
}) {
  const viewer = await requireViewer();

  assertChatMessageLength(input.message);

  return markChatPendingMessage({
    chatId: input.chatId,
    message: input.message,
    userId: viewer.id,
  });
}

export async function clearChatPendingMessageAction(chatId: string) {
  const viewer = await requireViewer();

  await clearChatPendingMessage({
    chatId,
    userId: viewer.id,
  });

  return { ok: true };
}

export async function skipChatAuthorizationAction(input: {
  readonly chatId: string;
  readonly events: readonly HandleMessageStreamEvent[];
  readonly session: SessionState;
}) {
  const viewer = await requireViewer();

  return skipChatAuthorization({
    chatId: input.chatId,
    events: input.events,
    session: input.session,
    userId: viewer.id,
  });
}

export async function pushChatEventAction(input: {
  readonly chatId: string;
  readonly event: HandleMessageStreamEvent;
  readonly eventIndex: number;
}) {
  const viewer = await requireViewer();

  await appendChatEvent({
    chatId: input.chatId,
    event: input.event,
    eventIndex: input.eventIndex,
    userId: viewer.id,
  });

  return { ok: true };
}

export async function saveChatSessionStateAction(input: {
  readonly chatId: string;
  readonly session: SessionState;
}) {
  const viewer = await requireViewer();

  await saveChatSessionState({
    chatId: input.chatId,
    session: input.session,
    userId: viewer.id,
  });

  return { ok: true };
}

export async function deleteChatAction(chatId: string) {
  const viewer = await requireViewer();

  await deleteChatForUser(chatId, viewer.id);

  return listChatsByUser(viewer.id);
}

async function requireViewer() {
  const setupStatus = await getSetupStatus();

  if (setupStatus.storageMode !== "database") {
    throw new Error("Database persistence is not enabled.");
  }

  const viewer = await getServerViewer(setupStatus);

  if (!viewer) {
    throw new Error("Sign in to continue.");
  }

  return viewer;
}
